// План specs/pricebook.md 1.1 (кейс .qa/tests/pricebook/PB-01). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: смета «QA-AUTO pb-est #df9bec …» с позицией «QA-AUTO pb-est-line …»; в конце — Delete.
import { test, expect } from '../../fixtures';
import {
  ROLE, addManualItem, expectNotInPriceBook, itemRow, openNewEstimate, openPriceBook, priceBookTotal, removeFromList, saveEstimate, stamp, watchPriceBookWrites,
} from './pricebook-helpers';

test.describe('Price Book — только ручные позиции (#df9bec)', () => {
  test('QA-AUTO: item typed in a new estimate stays only in the estimate, not added to Price Book #df9bec @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(ROLE);
    const s = stamp();
    const title = `QA-AUTO pb-est #df9bec ${s}`;
    const item = { name: `QA-AUTO pb-est-line ${s}`, price: '1' };
    try {
      // Шаг 1: Total Items до
      await openPriceBook(page);
      const before = await priceBookTotal(page);

      // Шаги 2–4: новая смета → Add Item (имени нет в Price Book) → Save
      const writes = watchPriceBookWrites(page);
      await openNewEstimate(page, title);
      await addManualItem(page, item);
      await expect(itemRow(page, item.name)).toHaveCount(1);
      await saveEstimate(page);
      // «מה רצוי»: הפריט נשמר רק במסמך עצמו — запросов записи в PriceBook нет
      expect(writes, 'POST/PATCH/PUT к PriceBook при добавлении позиции и сохранении сметы').toEqual([]);

      // Шаг 5: Price Book — число позиций то же, поиск пуст
      await expectNotInPriceBook(page, item.name, before);
      expect(writes, 'запросов записи в PriceBook нет').toEqual([]);
    } finally {
      await removeFromList(page, '/assessments', title);
    }
  });
});
